From addb399a15e0fc723729079b02489fceb2fae3f2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:43:08 +0100
Subject: [PATCH] applets/notifications: Unmute sounds if Do Not Disturb ended
 while logged out

Sounds were only unmuted when Do Not Disturb turned off, which never
happens at login once its end time has passed. Also unmute the stream
when it shows up muted by us while Do Not Disturb is no longer active.

BUG: 453281
---
 applets/notifications/global/Globals.qml | 25 ++++++++++++++++++++++++
 1 file changed, 25 insertions(+)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..6340858173 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -301,6 +301,15 @@ QtObject {
         });
     }

+    function restoreNotificationSounds() {
+        const stream = pulseAudio.item ? pulseAudio.item.notificationStream : null;
+        if (stream && stream.muted && !inhibited && notificationSettings.notificationSoundsInhibited) {
+            stream.unmute();
+            notificationSettings.notificationSoundsInhibited = false;
+            notificationSettings.save();
+        }
+    }
+
     function revokeInhibitions() {
         notificationSettings.notificationsInhibitedUntil = undefined;
         notificationSettings.revokeApplicationInhibitions();
@@ -733,6 +742,22 @@ QtObject {
         source: "PulseAudio.qml"
     }

+    // Do not disturb mode may have ended while the session wasn't running, in which case
+    // onInhibitedChanged never runs. Undo our mute once the notification stream shows up muted.
+    property Connections pulseAudioConnections: Connections {
+        target: globals.pulseAudio.item
+        function onNotificationStreamChanged() {
+            globals.restoreNotificationSounds();
+        }
+    }
+
+    property Connections notificationStreamConnections: Connections {
+        target: globals.pulseAudio.item ? globals.pulseAudio.item.notificationStream : null
+        function onMutedChanged() {
+            globals.restoreNotificationSounds();
+        }
+    }
+
     // Normally popups are repositioned through Qt.callLater but in case of e.g. screen geometry changes we want to compress that
     property Timer repositionTimer: Timer {
         interval: 250
-- 
